NEW_FILES = {'migrations/migrate_supermarket_gondolas.py': '#!/usr/bin/env python3\n"""\nmigrate_supermarket_gondolas.py  --  a supermarket\'s aisles are gondolas too\n=============================================================================\nOne-shot, idempotent migration over specs/*.json (Deli Counter 0.272.0).\n\n`migrate_store_gondolas.py` (0.149.0) made every store\'s aisles Zoo\'s\n`snack_gondola` and left the supermarkets\' `aisle_N` as boxes, because "a\nsupermarket aisle is not a snack aisle". The walker, walking seed 9205\'s\nsupermarket on 2026-10-26, met what that left: five 14 m dark blocks down the\nsales floor, read with the rest of the room as "far too dark" and alongside\nthe ramp\'s bare slab as "doesn\'t look finished" (the factory\'s\ndocs/findings/walk_2026-10-26_panel/, L4 and L3). A shelved gondola stocked\nwith packaged goods reads as a store\'s aisle; a box does not.\n\nTHEY FIT THE SPECIES: the supermarkets\' aisles are 1.4 x 14.0 x 2.0 m\n(supermarket_a01) and 1.4 x 12.0 x 2.0 m (supermarket_a03); Zoo\'s\n`snack_gondola` genome takes widths 1.2-14.0, depths 0.6-1.5 and heights\n1.2-2.2. Grocery stock in place of snacks is a Zoo variant for later, not a\nreason to keep a box.\n\nA SUPERMARKET is a spec whose file name begins `supermarket`. Nothing in\neither refers to an aisle by name outside its volume list (measured before\nit ran), so the rename breaks no reference. `lf_*` specs are skipped.\n\n    python migrations/migrate_supermarket_gondolas.py            # write specs/\n    python migrations/migrate_supermarket_gondolas.py --check    # report only; exit 1 if any\n    python migrations/migrate_supermarket_gondolas.py --dir D    # another spec directory\n"""\nimport glob\nimport io\nimport json\nimport os\nimport re\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n_AISLE = re.compile(r"aisle_(\\d+)")\n\n\ndef is_supermarket(path):\n    return os.path.basename(path).startswith("supermarket")\n\n\ndef renames(spec):\n    """``[(old, new)]``: every ``aisle_N`` volume to ``gondola_aisle_N``."""\n    names = [v.get("name", "") for v in spec.get("volumes") or []]\n    taken, out = set(names), []\n    for n in names:\n        m = _AISLE.fullmatch(n)\n        if not m:\n            continue\n        new = "gondola_aisle_" + m.group(1)\n        k = 2\n        while new in taken:\n            new = "gondola_aisle_%s_%d" % (m.group(1), k)\n            k += 1\n        taken.add(new)\n        out.append((n, new))\n    return out\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = os.path.join(HERE, "specs")\n    if "--dir" in argv:\n        root = argv[argv.index("--dir") + 1]\n    specs = count = 0\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        if os.path.basename(p).startswith("lf_") or not is_supermarket(p):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        todo = renames(d)\n        if not todo:\n            continue\n        specs += 1\n        count += len(todo)\n        print(f"[supermarket_gondolas] {os.path.basename(p)}: " + ", ".join(f"{a} -> {b}" for a, b in todo))\n        if check:\n            continue\n        m = dict(todo)\n        for v in d["volumes"]:\n            if v.get("name") in m:\n                v["name"] = m[v["name"]]\n        io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    verb = "need renaming" if check else "renamed"\n    print(f"[supermarket_gondolas] {specs} supermarket spec(s), {count} aisle(s) {verb}")\n    return 1 if check and count else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_supermarket_gondolas.py': '"""0.272.0 -- a supermarket\'s aisles are gondolas too (the factory\'s docs/findings/walk_2026-10-26_panel/, L4, L3).\n\nThe walker read seed 9205\'s supermarket as "far too dark" and "doesn\'t look finished": its sales floor was five 14 m\ndark boxes. They fit Zoo\'s `snack_gondola`, so they are routed to it. FAILS ON 0.271.0.\n"""\nimport json\nimport os\n\nimport migrate_supermarket_gondolas as M\nimport prop_species\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n\n\ndef test_every_supermarket_aisle_is_a_gondola():\n    assert M.main(["--check"]) == 0, "run: python migrations/migrate_supermarket_gondolas.py"\n    for name, n in (("supermarket_a01", 5), ("supermarket_a03", 4)):\n        d = json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n        names = [v["name"] for v in d["volumes"]]\n        assert not [x for x in names if M._AISLE.fullmatch(x)], name\n        gondolas = [x for x in names if prop_species.species_for_name(x) == "snack_gondola"]\n        assert len(gondolas) == n, (name, gondolas)\n\n\ndef test_they_fit_the_species():\n    zoo = os.environ.get("DC_ZOO_ROOT") or os.path.join(os.path.dirname(HERE), "zoo")\n    path = os.path.join(zoo, "zoo_keeper", "genome", "species", "snack_gondola.json")\n    if not os.path.isfile(path):\n        import pytest\n        pytest.skip("zoo is not beside this checkout (set DC_ZOO_ROOT)")\n    dims = json.load(open(path, encoding="utf-8"))["dimensions"]\n    checked = 0\n    for name in ("supermarket_a01", "supermarket_a03"):\n        d = json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n        for v in d["volumes"]:\n            if prop_species.species_for_name(v["name"]) != "snack_gondola":\n                continue\n            width, depth = max(v["size_x"], v["size_y"]), min(v["size_x"], v["size_y"])\n            assert dims["width"]["min"] <= width <= dims["width"]["max"], (name, v["name"], width)\n            assert dims["depth"]["min"] <= depth <= dims["depth"]["max"], (name, v["name"], depth)\n            assert dims["height"]["min"] <= v["size_z"] <= dims["height"]["max"], (name, v["name"])\n            checked += 1\n    assert checked == 9          # every aisle, so this cannot pass by finding none\n'}
CHANGELOG = '## [0.272.0] - a supermarket\'s aisles are gondolas too\n\n**The walker, walking seed 9205\'s supermarket, 2026-10-26**: "far too dark" and, of the level, "doesn\'t look finished".\nUnder an inspection light the sales floor\'s aisles were five 14 m plain boxes (the factory\'s\n`docs/findings/walk_2026-10-26_panel/`, L3 and L4).\n\n### Changed\n- **`migrations/migrate_supermarket_gondolas.py`** renames the supermarkets\' `aisle_N` volumes to `gondola_aisle_N`,\n  which `prop_species` routes to Zoo\'s `snack_gondola`: 5 in `supermarket_a01`, 4 in `supermarket_a03`.\n  - `migrate_store_gondolas.py` (0.149.0) had left them boxes because "a supermarket aisle is not a snack aisle".\n    They fit the species, though: 1.4 x 14.0 x 2.0 m and 1.4 x 12.0 x 2.0 m, against widths 1.2-14.0, depths\n    0.6-1.5 and heights 1.2-2.2. Grocery stock in place of snacks is a Zoo variant for later.\n- **`migrate_slush_machine.is_store` means a CONVENIENCE store and excludes supermarkets.** It reads "a sales floor\n  with `gondola_aisle` volumes", so the renamed supermarkets matched it, and six migrations would have given them a\n  slush station, a roller grill, window posters and signs. A supermarket\'s cooler wall and glass front are a decision\n  of their own, not this release\'s side effect.\n- `prop_species`\' note records the change; `test_store_gondolas` keeps only the pharmacy out.\n\n### Tests\n- `tests/test_supermarket_gondolas.py` (both fail on 0.271.0): every supermarket aisle is a gondola; they fit the\n  species, all 9 checked, so the test cannot pass by finding none.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.271.0', 'Deli Counter 0.272.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
